+    }
+  } else {
+    // one shot fusion
+    AINFO << "Combined classifier, one shot fusion";
+    for (auto& object : *objects) {
+      if (object->lidar_supplement.is_background) {
+        object->type_probs.assign(static_cast<int>(ObjectType::MAX_OBJECT_TYPE),
