+        object->type = ObjectType::UNKNOWN_UNMOVABLE;
+        object->type_probs[static_cast<int>(ObjectType::UNKNOWN_UNMOVABLE)] =
+            1.0;
+        continue;
+      }
+      if (!one_shot_fuser_ptr_->TypeFusion(option_, object)) {
+        AERROR << "Failed to fuse types, so continue.";
+      }
+    }
+  }
+  return true;
