+          has_found_nearest_lane_to_vehicle = true;
+          break;
+        }
+        ++nearest_lane_to_vehicle_index;
+      }
+      // The vehicle has not reached the nearest lane to the parking spot。
+      if (has_found_nearest_lane_to_vehicle &&
