-enum E_DECODER_RESULT {
-  E_DECODE_FAIL = -2,
-  E_PARAM_INVALID = -1,
-  E_DECODE_OK = 0,
-  E_FRAME_SPLIT = 1
-};
-
-enum RS_ECHO_MODE { RS_ECHO_DUAL = 0, RS_ECHO_MAX, RS_ECHO_LARS };
-
-typedef struct {
-  uint8_t year;
-  uint8_t month;
-  uint8_t day;
-  uint8_t hour;
-  uint8_t minute;
-  uint8_t second;
-  uint16_t ms;
