-#include <memory>
-#include <string>
-
-#include "modules/drivers/lidar/robosense/decoder/decoder_128.hpp"
-#include "modules/drivers/lidar/robosense/decoder/decoder_16.hpp"
-#include "modules/drivers/lidar/robosense/decoder/decoder_32.hpp"
