-void Brakecmd104::Reset() {
-  // TODO(QiL) you should check this manually
-  ignore_overrides_ = false;
-  enable_ = false;
-  clear_override_ = false;
-  clear_faults_ = false;
-  brake_cmd_ = 0.0;
