-      check_ok = check_ok && is_vcu_online && is_esp_online;
-    }
-    if (check_ok) {
-      return true;
-    } else {
-      AINFO << "Need to check response again.";
-    }
-    if (need_wait) {
-      --retry_num;
-      std::this_thread::sleep_for(
