-namespace {
-
-const int32_t kMaxFailAttempt = 10;
-const int32_t CHECK_RESPONSE_STEER_UNIT_FLAG = 1;
-const int32_t CHECK_RESPONSE_SPEED_UNIT_FLAG = 2;
