-    } else if (fbs2_240.rrwheeldirection() == Fbs2_240::RRWHEELDIRECTION_STOP) {
-      chassis_.mutable_wheel_speed()->set_wheel_direction_rr(
-          WheelSpeed::STANDSTILL);
-    } else {
-      chassis_.mutable_wheel_speed()->set_wheel_direction_rr(
