-TEST_F(WeyControllerTest, SetDrivingMode) {
-  Chassis chassis;
-  chassis.set_driving_mode(Chassis::COMPLETE_AUTO_DRIVE);
-
-  controller_.Init(params_, &sender_, &msg_manager_);
-
-  controller_.set_driving_mode(chassis.driving_mode());
