-void ChController::SetBeam(const ControlCommand& command) {
-  // Set low beam
-  if (command.signal().low_beam()) {
-    turnsignal_command_113_->set_low_beam_cmd(
-        Turnsignal_command_113::LOW_BEAM_CMD_ON);
