-void ChController::ResetVin() {
-  vehicle_mode_command_116_->set_vin_req_cmd(
-      Vehicle_mode_command_116::VIN_REQ_CMD_VIN_REQ_DISABLE);
-  AINFO << "Reset vin";
-  can_sender_->Update();
-}
