-void Ge3Controller::ResetProtocol() { message_manager_->ResetSendMessages(); }
-
-bool Ge3Controller::CheckChassisError() {
-  Ge3 chassis_detail;
-  message_manager_->GetSensorData(&chassis_detail);
-  if (!chassis_detail.has_check_response()) {
-    AERROR_EVERY(100) << "ChassisDetail has NO ge3 vehicle info."
-                      << chassis_detail.DebugString();
-    return false;
-  }
-
-  // check steer error
-  if (chassis_detail.has_scu_eps_311()) {
-    if (Scu_eps_311::EPS_FAULTST_FAULT ==
-        chassis_detail.scu_eps_311().eps_faultst()) {
-      return true;
-    }
-  }
-
-  // check vcu error
-  if (chassis_detail.has_scu_vcu_1_312() &&
-      Scu_vcu_1_312::VCU_FAULTST_NORMAL !=
-          chassis_detail.scu_vcu_1_312().vcu_faultst()) {
-    return true;
-  }
-
-  // check braking error
-  if (chassis_detail.has_scu_bcs_1_306()) {
-    if (Scu_bcs_1_306::BCS_FAULTST_FAULT ==
-        chassis_detail.scu_bcs_1_306().bcs_faultst()) {
-      return true;
-    }
-  }
-
-  // check gear error
-  if (chassis_detail.has_scu_vcu_1_312()) {
-    if (Scu_vcu_1_312::VCU_GEARFAULTST_FAULT ==
-        chassis_detail.scu_vcu_1_312().vcu_gearfaultst()) {
-      return true;
-    }
-  }
-
-  // check parking error
-  if (chassis_detail.has_scu_epb_310()) {
-    if (Scu_epb_310::EPB_FAULTST_FAULT ==
-        chassis_detail.scu_epb_310().epb_faultst()) {
-      return true;
-    }
-  }
-
-  // check the whole vehicle error
-  if (chassis_detail.has_scu_1_301()) {
-    if (Scu_1_301::SCU_FAULTST_NORMAL !=
-        chassis_detail.scu_1_301().scu_faultst()) {
-      return true;
-    }
-  }
-  return false;
-}
-
-void Ge3Controller::SecurityDogThreadFunc() {
-  int32_t vertical_ctrl_fail = 0;
-  int32_t horizontal_ctrl_fail = 0;
-
-  if (can_sender_ == nullptr) {
-    AERROR << "Failed to run SecurityDogThreadFunc() because can_sender_ is "
-              "nullptr.";
-    return;
-  }
-  while (!can_sender_->IsRunning()) {
-    std::this_thread::yield();
-  }
-
-  std::chrono::duration<double, std::micro> default_period{50000};
-  int64_t start = 0;
-  int64_t end = 0;
-  while (can_sender_->IsRunning()) {
-    start = ::apollo::cyber::Time::Now().ToMicrosecond();
-    const Chassis::DrivingMode mode = driving_mode();
-    bool emergency_mode = false;
-
-    // 1. horizontal control check
-    if ((mode == Chassis::COMPLETE_AUTO_DRIVE ||
-         mode == Chassis::AUTO_STEER_ONLY) &&
-        !CheckResponse(CHECK_RESPONSE_STEER_UNIT_FLAG, false)) {
-      ++horizontal_ctrl_fail;
-      if (horizontal_ctrl_fail >= kMaxFailAttempt) {
-        emergency_mode = true;
-        set_chassis_error_code(Chassis::MANUAL_INTERVENTION);
-      }
-    } else {
-      horizontal_ctrl_fail = 0;
-    }
-
-    // 2. vertical control check
-    if ((mode == Chassis::COMPLETE_AUTO_DRIVE ||
-         mode == Chassis::AUTO_SPEED_ONLY) &&
-        !CheckResponse(CHECK_RESPONSE_SPEED_UNIT_FLAG, false)) {
-      ++vertical_ctrl_fail;
-      if (vertical_ctrl_fail >= kMaxFailAttempt) {
-        emergency_mode = true;
-        set_chassis_error_code(Chassis::MANUAL_INTERVENTION);
-      }
-    } else {
-      vertical_ctrl_fail = 0;
-    }
-    if (CheckChassisError()) {
-      set_chassis_error_code(Chassis::CHASSIS_ERROR);
-      emergency_mode = true;
-    }
-
-    if (emergency_mode && mode != Chassis::EMERGENCY_MODE) {
-      set_driving_mode(Chassis::EMERGENCY_MODE);
-      message_manager_->ResetSendMessages();
-    }
-    end = ::apollo::cyber::Time::Now().ToMicrosecond();
-    std::chrono::duration<double, std::micro> elapsed{end - start};
-    if (elapsed < default_period) {
-      std::this_thread::sleep_for(default_period - elapsed);
-    } else {
-      AERROR << "Too much time consumption in Ge3Controller looping process:"
-             << elapsed.count();
-    }
-  }
-}
-
-bool Ge3Controller::CheckResponse(const int32_t flags, bool need_wait) {
-  int32_t retry_num = 20;
-  Ge3 chassis_detail;
-  bool is_eps_online = false;
-  bool is_vcu_online = false;
-  bool is_esp_online = false;
-
-  do {
-    if (message_manager_->GetSensorData(&chassis_detail) != ErrorCode::OK) {
-      AERROR_EVERY(100) << "get chassis detail failed.";
-      return false;
-    }
-    bool check_ok = true;
-    if (flags & CHECK_RESPONSE_STEER_UNIT_FLAG) {
-      is_eps_online = chassis_detail.has_check_response() &&
-                      chassis_detail.check_response().has_is_eps_online() &&
-                      chassis_detail.check_response().is_eps_online();
-      check_ok = check_ok && is_eps_online;
-    }
-
-    if (flags & CHECK_RESPONSE_SPEED_UNIT_FLAG) {
-      is_vcu_online = chassis_detail.has_check_response() &&
-                      chassis_detail.check_response().has_is_vcu_online() &&
-                      chassis_detail.check_response().is_vcu_online();
-      is_esp_online = chassis_detail.has_check_response() &&
-                      chassis_detail.check_response().has_is_esp_online() &&
-                      chassis_detail.check_response().is_esp_online();
-      check_ok = check_ok && is_vcu_online && is_esp_online;
-    }
-    if (check_ok) {
-      return true;
-    }
-    AINFO << "Need to check response again.";
-    if (need_wait) {
-      --retry_num;
-      std::this_thread::sleep_for(
-          std::chrono::duration<double, std::milli>(20));
-    }
-  } while (need_wait && retry_num);
-
-  AINFO << "check_response fail: is_eps_online:" << is_eps_online
-        << ", is_vcu_online:" << is_vcu_online
-        << ", is_esp_online:" << is_esp_online;
-  return false;
-}
