-  if (!CheckResponse(CHECK_RESPONSE_STEER_UNIT_FLAG, true)) {
-    AERROR << "Failed to switch to AUTO_STEER_ONLY mode.";
-    CheckChassisError();
-    Emergency();
-    return ErrorCode::CANBUS_ERROR;
-  }
-  set_driving_mode(Chassis::AUTO_STEER_ONLY);
