-      chassis_detail->mutable_light()->set_lincoln_wiper(Light::WIPER_WASH);
-      break;
-    case 9:
-      chassis_detail->mutable_light()->set_lincoln_wiper(Light::WIPER_AUTO_LOW);
-      break;
-    case 10:
-      chassis_detail->mutable_light()->set_lincoln_wiper(
