-  uint8_t data[8] = {0x01, 0x62, 0x63, 0x64, 0x51, 0x52, 0x53, 0x54};
-  version.Parse(data, length, &cd);
-  EXPECT_TRUE(cd.has_brake());
-  EXPECT_FALSE(cd.has_gas());
-  EXPECT_FALSE(cd.has_eps());
-
-  EXPECT_EQ(cd.brake().major_version(), 25699);
