-  cd.Clear();
-  version.Parse(data, length, &cd);
-  EXPECT_FALSE(cd.has_brake());
-  EXPECT_TRUE(cd.has_gas());
-  EXPECT_FALSE(cd.has_eps());
-  EXPECT_EQ(cd.gas().major_version(), 25699);
