-  EXPECT_FALSE(cd.has_brake());
-  EXPECT_FALSE(cd.has_gas());
-  EXPECT_TRUE(cd.has_eps());
-  EXPECT_EQ(cd.eps().major_version(), 25699);
-  EXPECT_EQ(cd.eps().minor_version(), 21073);
